toolScript:
import {
            FaceLandmarker,
            FilesetResolver
        } from "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3";
        const video = document.getElementById('scanner-video');
        const canvas = document.getElementById('overlay-canvas');
        const ctx = canvas.getContext('2d');
        const statusText = document.getElementById('status-text');
        const liveBtn = document.getElementById('live-btn');
        const scanLine = document.getElementById('scan-line');
        const resultBadge = document.getElementById('age-result');
        const faceGuide = document.getElementById('face-guide');
        const liveIndicator = document.getElementById('live-indicator');
        let faceLandmarker;
        let runningMode = "VIDEO";
        let stream = null;
        let lastVideoTime = -1;
        let results = undefined;
        let trackingActive = false;
        let isLive = false;
        function log(msg, type = 'default') {
            const term = document.getElementById('terminal');
            const content = document.getElementById('terminal-content');
            const line = document.createElement('div');
            const time = new Date().toLocaleTimeString().split(' ')[0];
            const colorClass = type === 'success' ? 'text-green-400' : (type === 'error' ? 'text-red-500' : 'text-slate-400');
            line.innerHTML = `<span class="opacity-30">[${time}]</span> <span class="${colorClass}">${msg}</span>`;
            content.appendChild(line);
            term.scrollTop = term.scrollHeight;
        }
        async function createFaceLandmarker() {
            log("Initializing MediaPipe WASM bundles...");
            try {
                const filesetResolver = await FilesetResolver.forVisionTasks(
                    "https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.3/wasm"
                );
                faceLandmarker = await FaceLandmarker.createFromOptions(filesetResolver, {
                    baseOptions: {
                        modelAssetPath: `https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task`,
                        delegate: "GPU"
                    },
                    outputFaceBlendshapes: true,
                    runningMode: runningMode,
                    numFaces: 1
                });
                log("Local Neural Inference Model loaded.", "success");
            } catch (e) {
                log("LOAD ERROR: Model synchronization failed.", "error");
            }
        }
        createFaceLandmarker();
        window.startWebcam = async function () {
            try {
                log("Requesting hardware sensor access...");
                stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
                video.srcObject = stream;
                video.style.display = 'block';
                statusText.style.display = 'none';
                faceGuide.style.display = 'block';
                liveBtn.disabled = false;
                trackingActive = true;
                log("Hardware synced. Tracking nodes engaged.", "success");
                document.getElementById('tracking-status').innerText = "Standby";
                document.getElementById('tracking-status').className = "text-orange-500 font-bold uppercase";
                predictWebcam();
            } catch (err) {
                log("HARDWARE ERROR: Permission denied.", "error");
            }
        };
        window.handleFileUpload = function (e) {
            const file = e.target.files[0];
            if (!file) return;
            log(`Frame detected: ${file.name}`);
            const reader = new FileReader();
            reader.onload = function (event) {
                const img = new Image();
                img.onload = function () {
                    if (stream) {
                        stream.getTracks().forEach(track => track.stop());
                        video.srcObject = null;
                        video.style.display = 'none';
                    }
                    trackingActive = false;
                    statusText.style.display = 'none';
                    faceGuide.style.display = 'none';
                    liveIndicator.style.display = 'none';
                    canvas.width = 640;
                    canvas.height = 480;
                    ctx.drawImage(img, 0, 0, 640, 480);
                    log("Static frame verified. Analyzing...", "success");
                    analyzeStaticImage(img);
                };
                img.src = event.target.result;
            };
            reader.readAsDataURL(file);
        }
        async function predictWebcam() {
            if (!trackingActive) return;
            // Ensure video has valid dimensions to prevent WASM crashes
            if (video.videoWidth === 0 || video.videoHeight === 0) {
                requestAnimationFrame(predictWebcam);
                return;
            }
            let startTimeMs = performance.now();
            if (lastVideoTime !== video.currentTime) {
                lastVideoTime = video.currentTime;
                if (faceLandmarker) {
                    results = faceLandmarker.detectForVideo(video, startTimeMs);
                }
            }
            canvas.width = video.clientWidth;
            canvas.height = video.clientHeight;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            if (results && results.faceLandmarks && results.faceLandmarks.length > 0) {
                drawMesh(results.faceLandmarks[0]);
                processBiometrics(results.faceBlendshapes[0], results.faceLandmarks[0]);
                document.getElementById('points-val').innerText = "468";
                document.getElementById('tracking-status').innerText = "TRACKING";
                document.getElementById('tracking-status').className = "text-green-500 font-bold uppercase";
                // Show result badge immediately on detection, regardless of "live mode" toggle
                resultBadge.style.display = 'block';
            } else {
                document.getElementById('points-val').innerText = "0";
                document.getElementById('tracking-status').innerText = "SEARCHING";
                document.getElementById('tracking-status').className = "text-orange-400 font-bold uppercase";
                // Only hide if we aren't locking it
                if (!isLive) resultBadge.style.display = 'none';
            }
            requestAnimationFrame(predictWebcam);
        }
        async function analyzeStaticImage(img) {
            if (!faceLandmarker) return;
            const resultsStatic = faceLandmarker.detect(img);
            if (resultsStatic.faceLandmarks && resultsStatic.faceLandmarks.length > 0) {
                drawMesh(resultsStatic.faceLandmarks[0]);
                processBiometrics(resultsStatic.faceBlendshapes[0], resultsStatic.faceLandmarks[0]);
                resultBadge.style.display = 'block';
                log("Biometric signal resolved.", "success");
            } else {
                log("ERROR: NO FACE DETECTED.", "error");
                resultBadge.style.display = 'none';
            }
        }
        function drawMesh(landmarks) {
            ctx.strokeStyle = 'rgba(251, 146, 60, 0.5)';
            ctx.lineWidth = 0.5;
            ctx.beginPath();
            for (let i = 0; i < landmarks.length; i++) {
                const x = landmarks[i].x * canvas.width;
                const y = landmarks[i].y * canvas.height;
                if (i % 5 === 0) {
                    ctx.moveTo(x, y);
                    ctx.arc(x, y, 1, 0, Math.PI * 2);
                }
            }
            ctx.stroke();
        }
        function processBiometrics(blendshapes, landmarks) {
            if (!blendshapes || !blendshapes.categories) return;
            const categories = blendshapes.categories;
            const scores = {};
            categories.forEach(c => scores[c.categoryName] = c.score);
            // EMOTION TELEMETRY CALCULATIONS
            // 1. JOY (Smile, Cheek Raise)
            const joyRaw = (scores.mouthSmileLeft + scores.mouthSmileRight + scores.cheekSquintLeft + scores.cheekSquintRight) / 2;
            const joyPct = Math.min(100, Math.max(0, joyRaw * 100 * 1.5)).toFixed(0);
            // 2. SURPRISE (Brow Inner/Outer Up, Eyes Wide)
            const surpriseRaw = (scores.browInnerUp + scores.browOuterUpLeft + scores.browOuterUpRight + scores.eyeWideLeft + scores.eyeWideRight) / 3;
            const surprisePct = Math.min(100, Math.max(0, surpriseRaw * 100 * 1.8)).toFixed(0);
            // 3. FOCUS (Brow Down, Squint)
            const focusRaw = (scores.browDownLeft + scores.browDownRight + scores.eyeSquintLeft + scores.eyeSquintRight) / 2;
            const focusPct = Math.min(100, Math.max(0, focusRaw * 100 * 1.5)).toFixed(0);
            // 4. SADNESS (Frown, Mouth Press)
            const sadRaw = (scores.mouthFrownLeft + scores.mouthFrownRight + scores.mouthPressLeft + scores.mouthPressRight) / 2;
            const sadPct = Math.min(100, Math.max(0, sadRaw * 100 * 2.0)).toFixed(0);
            // Update Bars
            document.getElementById('bar-joy').style.width = `${joyPct}%`;
            document.getElementById('score-joy').innerText = `${joyPct}%`;
            document.getElementById('bar-surprise').style.width = `${surprisePct}%`;
            document.getElementById('score-surprise').innerText = `${surprisePct}%`;
            document.getElementById('bar-focus').style.width = `${focusPct}%`;
            document.getElementById('score-focus').innerText = `${focusPct}%`;
            document.getElementById('bar-sad').style.width = `${sadPct}%`;
            document.getElementById('score-sad').innerText = `${sadPct}%`;
            // Calculate Symmetry
            const leftEyeX = landmarks[33].x;
            const rightEyeX = landmarks[263].x;
            const symmetryVal = (100 - Math.abs((0.5 - leftEyeX) - (rightEyeX - 0.5)) * 100).toFixed(1);
            // Valence (Positive/Negative sentiment score -1 to 1)
            const valence = (joyRaw - sadRaw).toFixed(2);
            let valenceText = "NEUTRAL";
            if (valence > 0.1) valenceText = "POSITIVE";
            if (valence < -0.1) valenceText = "NEGATIVE";
            document.getElementById('symmetry-val').innerText = `${symmetryVal}%`;
            document.getElementById('valence-val').innerText = valenceText;
            // Determine Dominant Emotion
            const emotions = [
                { name: "JOY", val: parseFloat(joyPct) },
                { name: "SURPRISE", val: parseFloat(surprisePct) },
                { name: "FOCUSED", val: parseFloat(focusPct) },
                { name: "SADNESS", val: parseFloat(sadPct) }
            ];
            // Sort by value descending
            emotions.sort((a, b) => b.val - a.val);
            let primary = "NEUTRAL";
            if (emotions[0].val > 10) {
                primary = emotions[0].name;
            }
            if (emotions[0].val > 80) {
                primary = `HIGH ${emotions[0].name}`;
            }
            document.getElementById('primary-emotion').innerText = primary;
        }
        window.toggleLiveMode = function () {
            if (isLive) {
                isLive = false;
                document.getElementById('live-btn-text').innerText = "Start Local Tracking";
                liveIndicator.style.display = 'none';
                log("Real-time telemetry stream suspended.");
            } else {
                isLive = true;
                document.getElementById('live-btn-text').innerText = "Stop Local Tracking";
                liveIndicator.style.display = 'block';
                log("Actual biometric monitoring active.", "success");
            }
        };
        window.resetScanner = function () {
            if (stream) {
                stream.getTracks().forEach(track => track.stop());
                video.srcObject = null;
            }
            trackingActive = false;
            isLive = false;
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            statusText.style.display = 'flex';
            faceGuide.style.display = 'none';
            liveBtn.disabled = true;
            resultBadge.style.display = 'none';
            document.getElementById('tracking-status').innerText = "Inactive";
            document.getElementById('tracking-status').className = "text-slate-400 font-bold uppercase";
            log("Hardware purged. System reset.");
        };

        log("Live Emotion AI Pro (MediaPipe WASM) Node initialized.");
